Task ID: java_enum_db_compat
Scenario: Database enum values no longer match Java enum names after a migration.

Instructions:
Find the compatibility bug introduced by this migration and suggest the smallest safe patch. Assume existing production rows already use the migrated values.

Project snapshot:

=== File: src/main/resources/db/migration/V42__payment_state_lowercase.sql ===
update payment_record set state = lower(state);

=== File: src/main/java/com/example/payment/PaymentState.java ===
package com.example.payment;

public enum PaymentState {
    PENDING,
    PROCESSING,
    COMPLETED
}

=== File: src/main/java/com/example/payment/PaymentRecordDO.java ===
package com.example.payment;

public class PaymentRecordDO {
    private String state;

    public String getState() {
        return state;
    }

    public void setState(String state) {
        this.state = state;
    }
}

=== File: src/main/java/com/example/payment/PaymentMapper.java ===
package com.example.payment;

public class PaymentMapper {
    public PaymentState toDomain(PaymentRecordDO record) {
        return PaymentState.valueOf(record.getState());
    }
}
